  const pending = replies<Message>();
  const events: Message[] = [];
  let next = 0;

  socket.addEventListener('message', (event) => {
    const parsed: unknown = JSON.parse(String(event.data));
    if (!isRecord(parsed)) return;
    const message = parsed as Message;
